source .venv/bin/activate && uv remove datasets >/dev/null 2>&1; mkdir -p datasets/raw_eval && cd datasets/raw_eval && curl -sL -o arc_easy.parquet https://huggingface.co/datasets/allenai/ai2_arc/resolve/main/ARC-Easy/test-00000-of-00001.parquet && curl -sL -o arc_challenge.parquet https://huggingface.co/datasets/allenai/ai2_arc/resolve/main/ARC-Challenge/test-00000-of-00001.parquet && curl -sL -o mmlu.parquet https://huggingface.co/datasets/cais/mmlu/resolve/main/all/test-00000-of-00001.parquet; ls -la; cd ../.. && python -I -c "
import pandas as pd, numpy as np
rng=np.random.default_rng(42); out=[]
for b,f in [('arc_easy','arc_easy'),('arc_challenge','arc_challenge'),('mmlu','mmlu')]:
    d=pd.read_parquet(f'datasets/raw_eval/{f}.parquet')
    if b!='mmlu': d=d[d.choices.apply(lambda c: len(c['label'])==4)]
    d=d.iloc[rng.choice(len(d),500,replace=False)]
    for i,r in d.iterrows():
        if b=='mmlu': out.append(dict(bench=b,qid=f'mmlu_{i}',question=r.question,choices=list(r.choices),answer=int(r.answer)))
        else:
            labels=list(r.choices['label']); out.append(dict(bench=b,qid=r.id,question=r.question,choices=list(r.choices['text']),answer=labels.index(r.answerKey)))
df=pd.DataFrame(out); df.to_json('datasets/eval_items/items.jsonl',orient='records',lines=True); print(df.bench.value_counts()); print(df.iloc[0].to_dict())
"; tail -3 logs/download_v1.log

